"""Migration utilities for legacy AUD_EVENT rows."""

from typing import Optional


def migrate_event(row: dict) -> dict:
    """Convert one legacy AUD_EVENT row to a modern event."""
    timestamp = row["EVT_TS"]
    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            f"{timestamp[0:4]}-{timestamp[4:6]}-{timestamp[6:8]}"
            f"T{timestamp[8:10]}:{timestamp[10:12]}:{timestamp[12:14]}"
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


class AuditStore:
    """An append-only in-memory audit event store."""

    def __init__(self) -> None:
        self._events: list[dict] = []

    def append(self, event: dict) -> None:
        """Append a defensive copy of an event."""
        self._events.append(dict(event))

    def events(self) -> list[dict]:
        """Return the stored events in append order as defensive copies."""
        return [dict(event) for event in self._events]

    def __len__(self) -> int:
        return len(self._events)


def migrate(
    rows: list[dict],
    store: Optional[AuditStore] = None,
) -> AuditStore:
    """Migrate rows in canonical EVT_ID order, skipping existing events."""
    if store is None:
        store = AuditStore()

    existing_ids = {event["evt_id"] for event in store.events()}

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        evt_id = int(row["EVT_ID"])
        if evt_id in existing_ids:
            continue
        store.append(migrate_event(row))
        existing_ids.add(evt_id)

    return store
